gdW(){return"\u062a\u0645 \u062a\u0635\u0645\u064a\u0645 \u062a\u0637\u0628\u064a\u0642\u0646\u0627 \u0644\u062d\u0644 \u0647\u0630\u0647 \u0627\u0644\u0645\u0634\u0643\u0644\u0629!"},
gdZ(){return"\u0643\u064a\u0641\u061f"},
gdY(){return"\u064a\u0645\u0643\u0646\u0643 \u0628\u0633\u0647\u0648\u0644\u0629 \u0625\u0646\u0634\u0627\u0621 \u0647\u064a\u0643\u0644: \u0645\u0646\u0632\u0644 - \u063a\u0631\u0641\u0629 - \u062e\u0632\u0627\u0646\u0629 - \u0635\u0646\u062f\u0648\u0642 - \u0634\u064a\u0621. \u062b\u0645 \u064a\u0645\u0643\u0646\u0643 \u0625\u0636\u0627\u0641\u0629 \u0627\u0633\u0645\u0647 \u0648\u0645\u0639\u0644\u0648\u0645\u0627\u062a\u0647 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u0627\u0644\u0625\u064a\u0635\u0627\u0644 \u0648\u0627\u0644\u0635\u0648\u0631. \u0628\u0639\u062f \u0641\u062a\u0631\u0629\u060c \u0633\u064a\u0643\u0648\u0646 \u0627\u0644\u0639\u062b\u0648\u0631 \u0639\u0644\u0649 \u0627\u0644\u0634\u064a\u0621 \u0633\u0647\u0644\u0627\u064b \u0644\u0644\u063a\u0627\u064a\u0629! \u0633\u064a\u062a\u0645\u0643\u0646 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0623\u064a\u0636\u064b\u0627 \u0645\u0646 \u0625\u0646\u0634\u0627\u0621 \u062a\u0642\u0631\u064a\u0631 \u0645\u0641\u0635\u0644 \u0644\u0634\u0631\u0643\u0627\u062a \u0627\u0644\u062a\u0623\u0645\u064a\u0646."},
ge3(){return"\u0627\u0644\u0637\u0628\u0627\u0639\u0629 \u0648\u0627\u0644\u0645\u0633\u062d \u0627\u0644\u0636\u0648\u0626\u064a."},
ge1(){return"\u064a\u0645\u0643\u0646\u0643 \u0625\u0646\u0634\u0627\u0621 \u0648\u0637\u0628\u0627\u0639\u0629 \u0631\u0645\u0648\u0632 \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0627\u0644\u0633\u0631\u064a\u0639\u0629 \u0639\u0628\u0631 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u062b\u0645 \u0625\u0631\u0641\u0627\u0642\u0647\u0627 \u0628\u0627\u0644\u0645\u0631\u0628\u0639\u0627\u062a \u0644\u0639\u0631\u0636 \u0645\u062d\u062a\u0648\u064a\u0627\u062a\u0647\u0627 \u0639\u0644\u0649 \u0627\u0644\u0641\u0648\u0631 \u0644\u0627\u062d\u0642\u064b\u0627! \u0643\u0645\u0627 \u064a\u0645\u0643\u0646\u0643 \u0625\u0646\u0634\u0627\u0621 \u062a\u0642\u0631\u064a\u0631 \u0644\u0634\u0631\u0643\u0629 \u0627\u0644\u062a\u0623\u0645\u064a\u0646 \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u0643 \u0623\u0648 \u062c\u062f\u0648\u0644 \u0628\u064a\u0627\u0646\u0627\u062a \u0644\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0634\u062e\u0635\u064a."},
ge2(){return"\u0627\u0644\u0628\u062d\u062b \u0639\u0646 \u0627\u0644\u0646\u0635 \u0627\u0644\u0643\u0627\u0645\u0644 \u0645\u062a\u0627\u062d \u0623\u064a\u0636\u064b\u0627!"},
ge5(){return"\u0627\u0644\u0633\u062d\u0627\u0628\u0629 \u0648\u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0629."},
ge4(){return"\u064a\u0645\u0643\u0646\u0643 \u062a\u0645\u0643\u064a\u0646 \u0627\u0644\u0645\u0632\u0627\u0645\u0646\u0629 \u0627\u0644\u0633\u062d\u0627\u0628\u064a\u0629 \u0644\u0645\u0634\u0627\u0631\u0643\u0629 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0645\u0639 \u0627\u0644\u0645\u0642\u0631\u0628\u064a\u0646 \u0648\u0627\u0633\u062a\u0639\u0627\u062f\u0629 \u062a\u0642\u062f\u0645\u0643 \u0628\u0633\u0647\u0648\u0644\u0629 \u0639\u0644\u0649 \u062c\u0647\u0627\u0632 \u0622\u062e\u0631! \u0625\u0646\u0647 \u0622\u0645\u0646\u060c \u0644\u0623\u0646\u0646\u0627 \u0627\u062c\u062a\u0632\u0646\u0627 \u0639\u0645\u0644\u064a\u0629 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u062a\u0642\u064a\u064a\u0645 \u0623\u0645\u0627\u0646 \u062a\u0637\u0628\u064a\u0642\u0627\u062a \u0627\u0644\u0633\u062d\u0627\u0628\u0629 \u0645\u0646 Google."},
ge0(){return"\u0627\u0644\u0639\u0645\u0644 \u062f\u0648\u0646 \u0627\u062a\u0635\u0627\u0644."},
ge_(){return'\u0628\u063a\u0636 \u0627\u0644\u0646\u0638\u0631 \u0639\u0646 \u0645\u0643\u0627\u0646 \u0648\u062c\u0648\u062f\u0643 - \u0633\u064a\u0639\u0645\u0644 \u0628\u0631\u0646\u0627\u0645\u062c "My Precious" \u062f\u0627\u0626\u0645\u064b\u0627. \u0625\u0630\u0627 \u0644\u0645 \u062a\u0642\u0645 \u0628\u0627\u0644\u0645\u0632\u0627\u0645\u0646\u0629 \u0645\u0639 \u0627\u0644\u0633\u062d\u0627\u0628\u0629\u060c \u0641\u0644\u0646 \u062a\u0643\u0648\u0646 \u0647\u0646\u0627\u0643 \u062d\u0627\u062c\u0629 \u0625\u0644\u0649 \u0627\u0644\u0625\u0646\u062a\u0631\u0646\u062a \u0639\u0644\u0649 \u0627\u0644\u0625\u0637\u0644\u0627\u0642!'},
gdU(){return"\u0627\u0646\u0647\u0627 \u0633\u0631\u064a\u0629."},
gdT(){return"\u0646\u062d\u0646 \u0646\u0633\u062a\u062e\u062f\u0645 \u0623\u062d\u062f\u062b \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0627\u062a \u0645\u0646 \u0634\u0631\u0643\u0627\u062a \u062a\u0643\u0646\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u0643\u0628\u064a\u0631\u0629 \u0644\u062d\u0645\u0627\u064a\u0629 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0648\u0639\u062f\u0645 \u0645\u0634\u0627\u0631\u0643\u062a\u0647\u0627 \u0645\u0639 \u0623\u0637\u0631\u0627\u0641 \u062b\u0627\u0644\u062b\u0629. \u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0627\u0644\u062b\u0645\u064a\u0646\u0629 \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u0643 \u0622\u0645\u0646\u0629."},
