geb(){return"\u0643\u0631\u0627\u062a \u0627\u0644\u0644\u062d\u0645 \u0627\u0644\u062f\u0646\u0645\u0627\u0631\u0643\u064a\u0629"},
gdM(){return"\u0627\u0644\u0645\u0639\u062c\u0646\u0627\u062a \u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064a\u0629 \u0648\u0627\u0644\u0643\u0639\u0643"},
gee(){return"\u0648\u062c\u0628\u0629 \u0627\u0644\u0625\u0641\u0637\u0627\u0631 \u0627\u0644\u0627\u0646\u062c\u0644\u064a\u0632\u064a\u0629"},
gdO(){return"\u0627\u0644\u062a\u0627\u0628\u0627\u0633 \u0627\u0644\u0627\u0633\u0628\u0627\u0646\u064a\u0629"},
