geg(){return"\u0627\u0644\u0643\u0631\u0648\u0627\u0633\u0648\u0646 \u0627\u0644\u0641\u0631\u0646\u0633\u064a"},
gej(){return"\u0645\u0639\u0628\u062f \u0647\u0646\u062f\u0648\u0633\u064a"},
