gel(){return"\u0623\u0631\u0632 \u062a\u064a\u0645\u0628\u0644 \u0627\u0644\u0625\u0646\u062f\u0648\u0646\u064a\u0633\u064a"},
gem(){return"\u0628\u064a\u062a\u0632\u0627 \u0627\u064a\u0637\u0627\u0644\u064a\u0629"},
gen(){return"\u0631\u0627\u0645\u064a\u0646 \u064a\u0627\u0628\u0627\u0646\u064a"},
geo(){return"\u0628\u064a\u0648\u0646\u062f\u064a\u062c\u064a \u0627\u0644\u0643\u0648\u0631\u064a\u0629"},
gep(){return"\u0648\u0627\u0641\u0644 \u0634\u0631\u0627\u0628 \u0647\u0648\u0644\u0646\u062f\u064a"},
geq(){return"\u0633\u0646\u062f\u0648\u064a\u0634\u0627\u062a \u0646\u0631\u0648\u064a\u062c\u064a\u0629"},
